// A MAVLink v2 frame parser written from scratch (no MAVLink library).
//
// Phase 4. YOU implement this in src/link/mavlink_parser.cpp.
// Tests: tests/test_mavlink_parser.cpp (frames generated by real pymavlink).
//
// MAVLink v2 frame layout:
//
//   offset  size  field
//   0       1     magic = 0xFD
//   1       1     len            payload length (trailing zero bytes may be trimmed!)
//   2       1     incompat_flags bit 0 (0x01) = frame is signed; any other bit = unsupported
//   3       1     compat_flags   ignore
//   4       1     seq            0..255, wraps
//   5       1     sysid
//   6       1     compid
//   7       3     msgid          little-endian, 24 bits
//   10      len   payload
//   10+len  2     checksum       little-endian; see crc.h
//   12+len  13    signature      only if incompat_flags & 0x01 (not verified here)
//
// Behaviour the tests check:
//  - push() accepts ANY chunking: a byte at a time, half a frame, several frames at once.
//    It returns every valid frame completed during that call, in arrival order.
//  - Bytes discarded while hunting for a 0xFD magic byte are counted in bytes_skipped.
//  - Only v2 is supported. A v1 frame (magic 0xFE) is just garbage to skip.
//  - Header with unsupported incompat_flags (anything except 0x01 or 0x00)
//      -> bad_header++, frame dropped, resume searching at the byte AFTER that magic byte.
//  - msgid not in the CRC_EXTRA table (crc_extra.h)
//      -> unknown_msgid++, frame dropped, resume searching at the byte AFTER that magic byte.
//  - Checksum mismatch
//      -> crc_errors++, frame dropped, resume searching at the byte AFTER that magic byte.
//    (Why resume right after the magic, not after the "frame"? Because if this was a fake
//    0xFD inside garbage, its "length" is meaningless and a real frame may start inside it.)
//  - Valid frame -> frames_ok++ and it is returned.
#pragma once

#include <cstddef>
#include <cstdint>
#include <vector>

namespace asl::link {

constexpr std::uint8_t kMagicV2 = 0xFD;
constexpr std::size_t kHeaderLen = 10;     // magic .. msgid
constexpr std::size_t kChecksumLen = 2;
constexpr std::size_t kSignatureLen = 13;
constexpr std::uint8_t kIncompatSigned = 0x01;

struct Frame {
    std::uint8_t seq{0};
    std::uint8_t sysid{0};
    std::uint8_t compid{0};
    std::uint32_t msgid{0};
    bool is_signed{false};
    std::vector<std::uint8_t> payload;  // exactly `len` bytes, as received
};

struct ParserStats {
    std::uint64_t frames_ok{0};
    std::uint64_t crc_errors{0};
    std::uint64_t unknown_msgid{0};
    std::uint64_t bad_header{0};
    std::uint64_t bytes_skipped{0};
};

class MavlinkParser {
public:
    /// Feed raw bytes from the link. Returns the frames completed in this call.
    std::vector<Frame> push(const std::uint8_t* data, std::size_t len);

    const ParserStats& stats() const { return stats_; }

private:
    ParserStats stats_;
    // Design (b): bytes not yet consumed. push() appends, scans frames from the front, and
    // erases the consumed prefix once at the end. "Resume after the magic byte" is simply
    // advancing the scan position by one. Never holds more than one partial frame (+ the
    // new chunk), at most 10 + 255 + 2 + 13 = 280 bytes before a decision is possible.
    std::vector<std::uint8_t> buf_;
};

}  // namespace asl::link
